const $=s=>document.querySelector(s);
const characters=['Character 1','Character 2','Character 3','Character 4'];
const escapeHTML=v=>v.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hairstyles=['Soft waves','Sleek bob','High bun','Long braid'];
const outfits=[['Weekend denim','Pink cardigan','City cargos'],['Midnight gown','Satin evening','Ivory suit'],['Sage kurta','Blue shalwar kameez','Rose kurta'],['Rose lehenga','Emerald sari','Violet anarkali']];
let state={stage:'character',name:'',skin:1,face:'oval',eyes:'almond',nose:'natural',mouth:'natural',hairColor:'original',character:1,culture:'eastern',occasion:'formal',outfit:9,hair:0,lip:null,blush:null,eye:null};
const images={}; const canvas=$('#doll'),ctx=canvas.getContext('2d');
const colors={lip:['#b94160','#c66e68','#952448','#df3655','#895044'],blush:['#e68499','#cf7d63','#b9617c'],eye:['#ae77aa','#b78651','#788697','#805951']};
const titles={character:['YOUR MUSE','Who will you style?','Choose a starting character, then personalise your features.'],outfit:['THE WARDROBE','A look for every mood.','Pick a piece. Make it yours.'],beauty:['THE BEAUTY ROOM','The finishing touches.','Choose your hair, then play with colour.'],finish:['YOUR FINAL LOOK','Made entirely yours.','Take a moment. Admire your creation.']};
function card(id,label,src,selected,sub=''){return `<button class="card ${selected?'selected':''}" data-${id}="${src.index}" aria-pressed="${selected}"><span class="art" style="background-image:url('assets/${src.file}');background-size:${src.size||'contain'};background-position:${src.position||'center'}"></span><span class="label">${label}${sub?`<small>${sub}</small>`:''}</span>${selected?'<span class="check">✓</span>':''}</button>`}
function render(){ $('.mirror').classList.toggle('detail',state.stage==='character'||state.stage==='beauty');const t=titles[state.stage];$('#eyebrow').textContent=t[0];$('#heading').textContent=t[1];$('#description').textContent=t[2];document.querySelectorAll('[data-stage]').forEach(b=>{b.classList.toggle('active',b.dataset.stage===state.stage);b.setAttribute('aria-current',b.dataset.stage===state.stage?'step':'false')});
let html='';if(state.stage==='character'){html=`<div class="name-field"><label for="character-name-input">Name your character <span>(optional)</span></label><input id="character-name-input" type="text" maxlength="32" autocomplete="off" placeholder="Enter a name" value="${escapeHTML(state.name)}"></div>`+'<div class="grid character-grid">'+characters.map((n,i)=>card('character',n,{file:`portrait-${i}.webp`,index:i},state.character===i)).join('')+'</div>'+customizer()}
if(state.stage==='outfit'){const col=(state.culture==='eastern'?2:0)+(state.occasion==='formal'?1:0);html=`<div class="filters"><button data-culture="western" class="${state.culture==='western'?'active':''}" aria-pressed="${state.culture==='western'}">Western</button><button data-culture="eastern" class="${state.culture==='eastern'?'active':''}" aria-pressed="${state.culture==='eastern'}">Eastern</button><div class="occasion"><button data-occasion="casual" class="${state.occasion==='casual'?'active':''}" aria-pressed="${state.occasion==='casual'}">Casual</button><button data-occasion="formal" class="${state.occasion==='formal'?'active':''}" aria-pressed="${state.occasion==='formal'}">Formal</button></div></div><div class="section-label">${state.culture==='eastern'?'SOUTH ASIAN':'WESTERN'} / ${state.occasion.toUpperCase()}</div><div class="grid">${outfits[col].map((n,r)=>card('outfit',n,{file:`outfit-${col*3+r}.webp`,index:col*3+r},state.outfit===col*3+r,state.occasion==='formal'?'Occasion wear':'Everyday style')).join('')}</div>`}
if(state.stage==='beauty'){html='<div class="section-label">HAIRSTYLE</div><div class="grid hair-grid">'+hairstyles.map((n,i)=>card('hair',n,{file:`hair-thumb-${i}.webp`,index:i},state.hair===i)).join('')+'</div>'+hairColors();for(const key of ['lip','blush','eye']){html+=`<div class="beauty-block"><div class="section-label">${{lip:'LIP COLOUR',blush:'BLUSH',eye:'EYESHADOW'}[key]}</div><div class="swatches"><button class="swatch none ${state[key]===null?'selected':''}" data-makeup="${key}" data-color="none" aria-label="No ${key}" aria-pressed="${state[key]===null}">∅</button>${colors[key].map(c=>`<button class="swatch ${state[key]===c?'selected':''}" style="background:${c}" data-makeup="${key}" data-color="${c}" aria-label="${key} ${c}" aria-pressed="${state[key]===c}"></button>`).join('')}</div></div>`}}
if(state.stage==='finish'){html=`<div class="finish-box"><h2>${outfits[Math.floor(state.outfit/3)][state.outfit%3]}</h2><p>A look styled by you, from your wardrobe choice to the last touch of colour.</p><div class="summary">${state.name.trim()?`<span>${escapeHTML(state.name.trim())}</span>`:''}<span>${state.outfit>=6?'Eastern':'Western'}</span><span>${Math.floor(state.outfit/3)%2?'Formal':'Casual'}</span><span>${hairstyles[state.hair]}</span></div></div><div class="finish-actions"><button class="secondary" data-stage="outfit">Change outfit</button><button class="secondary" data-stage="beauty">Adjust beauty</button></div>`}
$('#panel').innerHTML=html;const next={character:'Choose an outfit',outfit:'Hair & makeup',beauty:'See final look',finish:'Style another look'};$('#next').innerHTML=next[state.stage]+' <span>✦</span>';$('#footer-note').textContent=state.stage==='beauty'?'Every detail is your decision.':'A little tradition. A little reinvention.';draw()}
function draw(){if(!images.base)return;ctx.clearRect(0,0,480,800);ctx.drawImage(customFace(),0,0,480,800);if(images['outfit'+state.outfit])ctx.drawImage(images['outfit'+state.outfit],0,0,480,800);ctx.save();ctx.globalCompositeOperation='multiply';if(state.blush){ctx.globalAlpha=.3;ctx.fillStyle=state.blush;for(const x of [221,259]){ctx.beginPath();ctx.ellipse(x,98,10,5,0,0,Math.PI*2);ctx.fill()}}if(state.eye){ctx.globalAlpha=.45;ctx.fillStyle=state.eye;for(const x of [223,257]){ctx.beginPath();ctx.ellipse(x,78,9,3,0,0,Math.PI*2);ctx.fill()}}if(state.lip){ctx.globalAlpha=.75;ctx.fillStyle=state.lip;ctx.beginPath();ctx.ellipse(240,111,10,3,0,0,Math.PI*2);ctx.fill()}ctx.restore();if(images['hair'+state.hair])drawHair();$('#character-name').textContent=state.name.trim();$('#character-name').hidden=!state.name.trim();$('#look-name').textContent=outfits[Math.floor(state.outfit/3)][state.outfit%3];canvas.setAttribute('aria-label',`${state.name.trim()||'Your character'} wearing ${$('#look-name').textContent} with ${hairstyles[state.hair]}`)}
document.addEventListener('input',e=>{if(e.target.id==='character-name-input'){state.name=e.target.value.slice(0,32);draw()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.stage){state.stage=d.stage;render()}else if(d.character!==undefined){state.character=+d.character;state.skin=[0,1,2,3][state.character];render()}else if(d.skin!==undefined){state.skin=+d.skin;render()}else if(d.feature){state[d.feature]=d.value;render()}else if(d.haircolor){state.hairColor=d.haircolor;render()}else if(d.culture){state.culture=d.culture;render()}else if(d.occasion){state.occasion=d.occasion;render()}else if(d.outfit!==undefined){state.outfit=+d.outfit;render()}else if(d.hair!==undefined){state.hair=+d.hair;render()}else if(d.makeup){state[d.makeup]=d.color==='none'?null:d.color;render()}});
$('#next').onclick=()=>{state.stage={character:'outfit',outfit:'beauty',beauty:'finish',finish:'character'}[state.stage];render()};$('#reset').onclick=()=>{state={stage:'character',name:'',skin:1,face:'oval',eyes:'almond',nose:'natural',mouth:'natural',hairColor:'original',character:1,culture:'eastern',occasion:'formal',outfit:9,hair:0,lip:null,blush:null,eye:null};render()};
async function load(){const files=[['hairSheet','hair-sheet.webp'],...Array.from({length:4},(_,i)=>['base'+i,`base-${i}.webp`]),...Array.from({length:12},(_,i)=>['outfit'+i,`outfit-${i}.webp`]),...Array.from({length:4},(_,i)=>['hair'+i,`hair-${i}.webp`])];try{await Promise.all(files.map(([k,f])=>new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>{images[k]=im;resolve()};im.onerror=reject;im.src='assets/'+f})));images.base=true;$('#loading').hidden=true;render()}catch{$('#loading').textContent='Artwork could not load. Please refresh to try again.'}}


const toneOptions=[['Fair','#edbc9a'],['Tan','#cd915e'],['Deep','#804522'],['Medium','#b97b48']];
const hairOptions=[['original','Natural','#493027'],['black','Black','#17131a'],['brown','Chocolate','#603b29'],['blonde','Honey blonde','#d3a45c'],['auburn','Auburn','#a24f30'],['silver','Silver','#c6c1c2'],['rose','Rose','#c77794']];
function customizer(){return `<div class="beauty-block"><div class="section-label">SKIN TONE</div><div class="swatches">${toneOptions.map(([n,c],i)=>`<button class="swatch ${state.skin===i?'selected':''}" style="background:${c}" data-skin="${i}" aria-label="${n} skin tone" aria-pressed="${state.skin===i}" title="${n}"></button>`).join('')}</div></div>`+Object.entries({face:['Face shape',['oval','round','defined']],eyes:['Eye shape',['almond','round','soft']],nose:['Nose',['natural','narrow','wide']],mouth:['Lips',['natural','full','soft']]}).map(([key,[name,options]])=>`<div class="feature-row"><span>${name}</span><div class="feature-options">${options.map(v=>`<button data-feature="${key}" data-value="${v}" class="${state[key]===v?'selected':''}" aria-pressed="${state[key]===v}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div></div>`).join('')}
function hairColors(){return `<div class="beauty-block"><div class="section-label">HAIR COLOUR</div><div class="swatches">${hairOptions.map(([v,n,c])=>`<button class="swatch ${state.hairColor===v?'selected':''}" data-haircolor="${v}" style="background:${c}" title="${n}" aria-label="${n} hair" aria-pressed="${state.hairColor===v}"></button>`).join('')}</div><div class="colour-caption">${hairOptions.find(o=>o[0]===state.hairColor)[1]}</div></div>`}
const faceCache=new Map(),hairCache=new Map();
function surface(){const c=document.createElement('canvas');c.width=480;c.height=800;return c}
function customFace(){const key=[state.skin,state.face,state.eyes,state.nose,state.mouth].join(':');if(faceCache.has(key))return faceCache.get(key);const c=surface(),cx=c.getContext('2d');cx.drawImage(images['base'+state.skin],0,0);const src=cx.getImageData(0,0,480,800),result=cx.getImageData(0,0,480,800);const gauss=(x,y,x0,y0,sx,sy)=>Math.exp(-((x-x0)**2/(2*sx*sx)+(y-y0)**2/(2*sy*sy)));
// Resample the existing painted face with gentle, blended feature deformations.
for(let y=35;y<135;y++)for(let x=185;x<295;x++){let sx=x,sy=y;const cheek=gauss(x,y,240,104,45,15);sx+=(x-240)*({oval:0,round:-.10,defined:.09}[state.face])*cheek;
for(const ex of [222,257]){const w=gauss(x,y,ex,77,12,7);if(state.eyes==='round'){sx+=(x-ex)*.07*w;sy-=(y-77)*.24*w}else if(state.eyes==='soft'){sx-=(x-ex)*.08*w;sy+=(y-77)*.13*w}}
const n=gauss(x,y,240,94,11,9);sx+=(x-240)*({natural:0,narrow:.26,wide:-.22}[state.nose])*n;
const l=gauss(x,y,240,108,13,6);if(state.mouth==='full'){sy-=(y-108)*.28*l;sx-=(x-240)*.10*l}else if(state.mouth==='soft'){sx+=(x-240)*.12*l;sy+=(y-108)*.12*l}
const x0=Math.floor(sx),y0=Math.floor(sy),fx=sx-x0,fy=sy-y0,d=(y*480+x)*4;for(let ch=0;ch<4;ch++){const at=(xx,yy)=>src.data[(yy*480+xx)*4+ch];result.data[d+ch]=at(x0,y0)*(1-fx)*(1-fy)+at(x0+1,y0)*fx*(1-fy)+at(x0,y0+1)*(1-fx)*fy+at(x0+1,y0+1)*fx*fy}}
cx.putImageData(result,0,0);if(faceCache.size>=24)faceCache.delete(faceCache.keys().next().value);faceCache.set(key,c);return c}
function tintedHair(){const key=state.hair+':'+state.hairColor;if(hairCache.has(key))return hairCache.get(key);const c=surface(),cx=c.getContext('2d');if(images.hairSheet){const fits=[{left:49,top:38,width:351,height:519,center:226,forehead:125},{left:471,top:43,width:242,height:264,center:598,forehead:125},{left:855,top:5,width:204,height:344,center:957,forehead:150},{left:1213,top:33,width:240,height:542,center:1325,forehead:125}];const f=fits[state.hair],scaleX=.52,scaleY=.53,x=240-(f.center-f.left)*scaleX;if(state.hair===2){cx.drawImage(images.hairSheet,f.left,5,f.width,120,x,3,f.width*scaleX,32);cx.drawImage(images.hairSheet,f.left,125,f.width,224,x,35,f.width*scaleX,224*scaleY)}else{const y=48+(f.top-f.forehead)*scaleY;cx.drawImage(images.hairSheet,f.left,f.top,f.width,f.height,x,y,f.width*scaleX,f.height*scaleY)}}else{cx.drawImage(images['hair'+state.hair],0,0)}if(state.hairColor!=='original'){const target=hairOptions.find(o=>o[0]===state.hairColor)[2],rgb=[1,3,5].map(i=>parseInt(target.slice(i,i+2),16));const im=cx.getImageData(0,0,480,800);for(let i=0;i<im.data.length;i+=4){if(!im.data[i+3])continue;const lum=(im.data[i]*.2126+im.data[i+1]*.7152+im.data[i+2]*.0722)/255;const factor=.24+lum*2.0;for(let j=0;j<3;j++)im.data[i+j]=Math.min(255,rgb[j]*factor)}cx.putImageData(im,0,0)}if(hairCache.size>=16)hairCache.delete(hairCache.keys().next().value);hairCache.set(key,c);return c}
function drawHair(){ctx.drawImage(tintedHair(),0,0)}

render();load();
